<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\OperatingUnitService;
use EventMenu\Services\RefundService;

Auth::requirePermission('payments.manage');$tenantId=em_require_tenant();
try{$unit=(new OperatingUnitService())->requireCurrent();}catch(Throwable$e){em_header('Financeiro / Pagamentos','payments');?><div class="alert error"><?= Security::e($e->getMessage()) ?></div><?php em_footer();return;}$unitId=(int)$unit['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    try{if($action==='refund'){Auth::requirePermission('refunds.manage');$r=(new RefundService())->requestFull((int)($_POST['payment_id']??0),(string)($_POST['reason']??''));em_flash($r['status']==='completed'?'ok':'error',$r['status']==='completed'?'Estorno integral concluído.':'Estorno solicitado ao provedor. Status: '.$r['status'].'.');}elseif($action==='reconcile-refund'){Auth::requirePermission('refunds.manage');$r=(new RefundService())->reconcile((int)($_POST['refund_id']??0));em_flash($r['status']==='completed'?'ok':'error',$r['status']==='completed'?'Estorno confirmado e concluído.':'O provedor ainda não confirmou o estorno.');}else throw new RuntimeException('Ação inválida.');}catch(Throwable$e){em_flash('error',$e->getMessage());}em_go('payments');
}
$provider=trim((string)($_GET['provider']??''));$status=trim((string)($_GET['status']??''));$q=trim((string)($_GET['q']??''));
$sql='SELECT p.*,o.status order_status,o.payment_status order_payment_status,c.name customer_name,r.id refund_id,r.status refund_status,r.reason refund_reason FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN refunds r ON r.tenant_id=p.tenant_id AND r.payment_id=p.id WHERE p.tenant_id=? AND o.unit_id=?';$args=[$tenantId,$unitId];if($provider!==''){$sql.=' AND p.provider=?';$args[]=$provider;}if($status!==''){$sql.=' AND p.status=?';$args[]=$status;}if($q!==''){if(ctype_digit(ltrim($q,'#'))){$sql.=' AND o.id=?';$args[]=(int)ltrim($q,'#');}else{$sql.=' AND (c.name LIKE ? OR p.provider_payment_id LIKE ?)';$like='%'.$q.'%';$args[]=$like;$args[]=$like;}}$sql.=' ORDER BY p.id DESC LIMIT 250';$s=$pdo->prepare($sql);$s->execute($args);$payments=$s->fetchAll();
$stats=[];$statSql=[
 'paid'=>'SELECT COALESCE(SUM(p.amount_cents),0) FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status="paid"',
 'pending'=>'SELECT COUNT(*) FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status IN ("created","pending","authorized")',
 'failed'=>'SELECT COUNT(*) FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status="failed"',
 'refunded'=>'SELECT COALESCE(SUM(p.amount_cents),0) FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status="refunded"',
 'duplicates'=>'SELECT COUNT(*) FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status="duplicate_paid"',
 'duplicate_amount'=>'SELECT COALESCE(SUM(p.amount_cents),0) FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status="duplicate_paid"'];foreach($statSql as$k=>$sqlStat){$x=$pdo->prepare($sqlStat);$x->execute([$tenantId,$unitId]);$stats[$k]=$x->fetchColumn();}
$providerTotals=[];$pt=$pdo->prepare('SELECT p.provider,COALESCE(SUM(p.amount_cents),0) amount FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status="paid" GROUP BY p.provider ORDER BY amount DESC');$pt->execute([$tenantId,$unitId]);foreach($pt->fetchAll()as$row)$providerTotals[(string)$row['provider']]=(int)$row['amount'];$providerGrand=max(1,array_sum($providerTotals));
$daily=[];$dp=$pdo->prepare('SELECT p.created_at,p.amount_cents FROM payments p JOIN orders o ON o.id=p.order_id AND o.tenant_id=p.tenant_id WHERE p.tenant_id=? AND o.unit_id=? AND p.status="paid" ORDER BY p.id DESC LIMIT 500');$dp->execute([$tenantId,$unitId]);foreach($dp->fetchAll()as$row){$key=date('d/m',strtotime((string)$row['created_at']));$daily[$key]=($daily[$key]??0)+(int)$row['amount_cents'];}$daily=array_slice(array_reverse($daily,true),-8,null,true);$dailyMax=max(1,$daily?max($daily):1);
$webhooks=[];if(Auth::can('audit.view')){$w=$pdo->prepare('SELECT * FROM webhook_events WHERE tenant_id=? ORDER BY id DESC LIMIT 100');$w->execute([$tenantId]);$webhooks=$w->fetchAll();}
em_header('Financeiro / Pagamentos','payments');
?>
<section class="page-hero"><div><span class="eyebrow">FINANCEIRO · <?= Security::e($unit['name']) ?></span><h2>Recebimentos e conciliação</h2><p>Transações e estornos desta tela pertencem somente à unidade selecionada.</p></div><div class="hero-actions"><a class="button secondary" href="<?= Security::e(app_url('?route=cash')) ?>">Turno de caixa</a><a class="button secondary" href="<?= Security::e(app_url('?route=reports')) ?>">Relatórios</a></div></section>
<section class="grid finance-summary"><div class="card metric"><span class="muted">Faturamento confirmado</span><strong><?= em_money($stats['paid']) ?></strong></div><div class="card metric"><span class="muted">Estornado</span><strong><?= em_money($stats['refunded']) ?></strong></div><div class="card metric"><span class="muted">Pendentes</span><strong><?= (int)$stats['pending'] ?></strong></div><div class="card metric"><span class="muted">Falharam</span><strong><?= (int)$stats['failed'] ?></strong></div></section>
<?php if((int)$stats['duplicates']>0):?><div class="alert error" style="margin-top:14px"><strong>Atenção:</strong> <?= (int)$stats['duplicates'] ?> cobrança(s) duplicada(s), totalizando <?= em_money($stats['duplicate_amount']) ?> nesta unidade.</div><?php endif;?>
<section class="finance-methods" style="margin-top:14px"><article class="card"><div class="section-head"><div><span class="eyebrow">EVOLUÇÃO</span><h2>Faturamento recente</h2></div></div><div class="chart-bars"><?php if(!$daily):?><div class="muted">Ainda não há pagamentos confirmados.</div><?php else:foreach($daily as$label=>$value):$height=max(7,(int)round($value*100/$dailyMax));?><div class="chart-bar" style="height:<?= $height ?>%" title="<?= Security::e($label.' · '.em_money($value)) ?>"><span><?= Security::e($label) ?></span></div><?php endforeach;endif;?></div></article><article class="card"><div class="section-head"><div><span class="eyebrow">MÉTODOS</span><h2>Por provedor</h2></div></div><div class="method-list"><?php foreach($providerTotals as$name=>$amount):$pct=(int)round($amount*100/$providerGrand);?><div class="method-row"><span><?= Security::e(ucfirst($name)) ?></span><div class="channel-track"><div class="channel-fill" style="width:<?= $pct ?>%"></div></div><strong><?= $pct ?>%</strong></div><?php endforeach;?><?php if(!$providerTotals):?><span class="muted">Sem pagamentos confirmados.</span><?php endif;?></div></article></section>
<section class="card" style="margin-top:14px"><div class="section-head"><div><span class="eyebrow">TRANSAÇÕES · <?= Security::e($unit['name']) ?></span><h2>Movimentações recentes</h2></div></div><form method="get" class="form-grid" style="margin-bottom:12px"><input type="hidden" name="route" value="payments"><label class="span-2">Buscar pedido, cliente ou transação<input name="q" value="<?= Security::e($q) ?>" placeholder="#123 ou ID do provedor"></label><label>Provedor<select name="provider"><option value="">Todos</option><?php foreach(['stripe','pagbank','mercadopago','manual']as$pv):?><option value="<?= $pv ?>"<?= em_selected($provider,$pv) ?>><?= Security::e(ucfirst($pv)) ?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="">Todos</option><?php foreach(['created','pending','authorized','paid','duplicate_paid','failed','cancelled','refunded','partially_refunded']as$st):?><option value="<?= $st ?>"<?= em_selected($status,$st) ?>><?= Security::e($st) ?></option><?php endforeach;?></select></label><div class="actions span-2"><button class="secondary">Filtrar</button><a class="button secondary" href="<?= Security::e(app_url('?route=payments')) ?>">Limpar</a></div></form><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Pedido</th><th>Cliente</th><th>Método</th><th>Valor</th><th>Status</th><th>Transação</th><th>Ações</th></tr></thead><tbody><?php foreach($payments as$p):?><tr><td><?= Security::e($p['created_at']??'') ?></td><td><a href="<?= Security::e(app_url('?route=orders&view='.(int)$p['order_id'])) ?>"><strong>#<?= (int)$p['order_id'] ?></strong></a></td><td><?= Security::e($p['customer_name']??'—') ?></td><td><?= Security::e(ucfirst((string)$p['provider'])) ?></td><td><strong><?= em_money($p['amount_cents']) ?></strong></td><td><span class="badge"><?= Security::e($p['status']) ?></span><?php if($p['status']==='duplicate_paid'):?><br><small class="muted">Não reaplicar efeitos do pedido</small><?php endif;?></td><td><code><?= Security::e($p['provider_payment_id']??'—') ?></code></td><td><?php if($p['refund_id']):?><span class="badge"><?= Security::e($p['refund_status']) ?></span><br><small><?= Security::e($p['refund_reason']??'') ?></small><?php if(Auth::can('refunds.manage')&&$p['refund_status']==='provider_pending'):?><form method="post" style="margin-top:6px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="reconcile-refund"><input type="hidden" name="refund_id" value="<?= (int)$p['refund_id'] ?>"><button class="secondary compact">Reverificar</button></form><?php elseif(Auth::can('refunds.manage')&&$p['refund_status']==='failed'):?><form method="post" style="margin-top:6px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="refund"><input type="hidden" name="payment_id" value="<?= (int)$p['id'] ?>"><input type="hidden" name="reason" value="<?= Security::e($p['refund_reason']??'Nova tentativa de estorno') ?>"><button class="secondary compact">Tentar novamente</button></form><?php endif;?><?php elseif(Auth::can('refunds.manage')&&in_array($p['status'],['paid','duplicate_paid'],true)):?><?php $duplicate=$p['status']==='duplicate_paid';?><form method="post" onsubmit="return confirm('<?= $duplicate?'Confirmar devolução da cobrança duplicada?':'Confirmar estorno integral desta transação?' ?>')"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="refund"><input type="hidden" name="payment_id" value="<?= (int)$p['id'] ?>"><input name="reason" maxlength="500" required minlength="5" placeholder="<?= $duplicate?'Cobrança duplicada':'Motivo do estorno' ?>" style="min-width:160px"><button class="secondary compact" style="margin-top:5px"><?= $duplicate?'Devolver duplicado':'Estornar' ?></button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="8">Nenhuma transação encontrada nesta unidade.</td></tr><?php endif;?></tbody></table></div></section>
<?php if(Auth::can('audit.view')):?><details class="technical-details" style="margin-top:12px"><summary>Webhooks e validação técnica da empresa</summary><section class="card"><div class="alert">Webhooks são recebidos no contexto da empresa e podem atender transações de mais de uma unidade. A tabela abaixo é técnica e, por isso, permanece consolidada.</div><div class="table-wrap"><table class="table"><thead><tr><th>Provedor</th><th>ID evento</th><th>Assinatura</th><th>Status</th><th>Processado</th></tr></thead><tbody><?php foreach($webhooks as$w):?><tr><td><?= Security::e($w['provider']) ?></td><td><code><?= Security::e($w['external_event_id']) ?></code></td><td><?= $w['signature_valid']?'Válida':'Inválida' ?></td><td><?= Security::e($w['status']) ?></td><td><?= Security::e($w['processed_at']??'—') ?></td></tr><?php endforeach;?></tbody></table></div></section></details><?php endif;?>
<?php em_footer();
